CREATE TYPE "CategoryCapabilityKey" AS ENUM ('BOOKING','AVAILABILITY','PROFESSIONAL_MATCHING','RESULT','PORTFOLIO','BEFORE_AFTER','CONSULTATION','PHOTO_INPUT','AI_ANALYSIS','PRODUCT_RECOMMENDATION','MULTI_SESSION','RESOURCE_REQUIRED','ROOM_REQUIRED','EQUIPMENT_REQUIRED','GROUP_BOOKING','DURATION_VARIANTS','ADD_ON_SERVICES','CUSTOM_ATTRIBUTES');
CREATE TYPE "CategoryAttributeType" AS ENUM ('STRING','NUMBER','BOOLEAN','ENUM','MULTI_ENUM','DATE','DURATION');
CREATE TABLE "PlatformCategory" ("id" TEXT PRIMARY KEY,"key" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PlatformSubcategory" ("id" TEXT PRIMARY KEY,"categoryId" TEXT NOT NULL REFERENCES "PlatformCategory"("id") ON DELETE CASCADE,"key" TEXT NOT NULL,"name" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,UNIQUE("categoryId","key"));
CREATE TABLE "PlatformServiceType" ("id" TEXT PRIMARY KEY,"categoryId" TEXT NOT NULL REFERENCES "PlatformCategory"("id") ON DELETE CASCADE,"subcategoryId" TEXT REFERENCES "PlatformSubcategory"("id") ON DELETE SET NULL,"key" TEXT NOT NULL,"name" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,UNIQUE("categoryId","key"));
CREATE TABLE "PlatformCategoryCapability" ("id" TEXT PRIMARY KEY,"categoryId" TEXT NOT NULL REFERENCES "PlatformCategory"("id") ON DELETE CASCADE,"capability" "CategoryCapabilityKey" NOT NULL,"configuration" JSONB,UNIQUE("categoryId","capability"));
CREATE TABLE "CategoryAttributeDefinition" ("id" TEXT PRIMARY KEY,"categoryId" TEXT NOT NULL REFERENCES "PlatformCategory"("id") ON DELETE CASCADE,"serviceTypeId" TEXT REFERENCES "PlatformServiceType"("id") ON DELETE CASCADE,"key" TEXT NOT NULL,"label" TEXT NOT NULL,"type" "CategoryAttributeType" NOT NULL,"required" BOOLEAN NOT NULL DEFAULT false,"minValue" DECIMAL(16,4),"maxValue" DECIMAL(16,4),"defaultValue" JSONB,"isActive" BOOLEAN NOT NULL DEFAULT true,UNIQUE("categoryId","serviceTypeId","key"));
CREATE TABLE "CategoryAttributeOption" ("id" TEXT PRIMARY KEY,"definitionId" TEXT NOT NULL REFERENCES "CategoryAttributeDefinition"("id") ON DELETE CASCADE,"value" TEXT NOT NULL,"label" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,UNIQUE("definitionId","value"));
CREATE TABLE "TenantCategoryConfiguration" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE CASCADE,"categoryId" TEXT NOT NULL REFERENCES "PlatformCategory"("id") ON DELETE CASCADE,"subcategoryId" TEXT REFERENCES "PlatformSubcategory"("id") ON DELETE CASCADE,"serviceTypeId" TEXT REFERENCES "PlatformServiceType"("id") ON DELETE CASCADE,"enabled" BOOLEAN NOT NULL DEFAULT true,"settings" JSONB,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("businessId","categoryId","subcategoryId","serviceTypeId"));
ALTER TABLE "Service" ADD COLUMN "platformCategoryId" TEXT REFERENCES "PlatformCategory"("id") ON DELETE SET NULL, ADD COLUMN "platformSubcategoryId" TEXT REFERENCES "PlatformSubcategory"("id") ON DELETE SET NULL, ADD COLUMN "platformServiceTypeId" TEXT REFERENCES "PlatformServiceType"("id") ON DELETE SET NULL;
CREATE TABLE "ServiceAttributeValue" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"serviceId" TEXT NOT NULL,"definitionId" TEXT NOT NULL REFERENCES "CategoryAttributeDefinition"("id") ON DELETE RESTRICT,"stringValue" TEXT,"numberValue" DECIMAL(16,4),"booleanValue" BOOLEAN,"dateValue" TIMESTAMP(3),"durationMinutes" INTEGER,"enumValues" TEXT[] NOT NULL,UNIQUE("serviceId","definitionId"),FOREIGN KEY ("businessId","serviceId") REFERENCES "Service"("businessId","id") ON DELETE CASCADE);
CREATE TABLE "PlatformResourceType" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE CASCADE,"key" TEXT NOT NULL,"name" TEXT NOT NULL,UNIQUE("businessId","key"));
CREATE TABLE "PlatformResource" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE CASCADE,"resourceTypeId" TEXT NOT NULL REFERENCES "PlatformResourceType"("id") ON DELETE RESTRICT,"name" TEXT NOT NULL,"capacity" INTEGER NOT NULL DEFAULT 1,"isActive" BOOLEAN NOT NULL DEFAULT true,UNIQUE("businessId","id"));
CREATE TABLE "ServiceResourceRequirement" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"serviceId" TEXT NOT NULL,"resourceTypeId" TEXT NOT NULL REFERENCES "PlatformResourceType"("id") ON DELETE RESTRICT,"quantity" INTEGER NOT NULL DEFAULT 1,UNIQUE("serviceId","resourceTypeId"),FOREIGN KEY ("businessId","serviceId") REFERENCES "Service"("businessId","id") ON DELETE CASCADE);
CREATE TABLE "ProfessionalCategoryAssignment" ("businessId" TEXT NOT NULL,"staffId" TEXT NOT NULL,"categoryId" TEXT NOT NULL REFERENCES "PlatformCategory"("id") ON DELETE CASCADE,"isActive" BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY("staffId","categoryId"),FOREIGN KEY ("businessId","staffId") REFERENCES "Staff"("businessId","id") ON DELETE CASCADE);
CREATE TABLE "ProfessionalServiceTypeAssignment" ("businessId" TEXT NOT NULL,"staffId" TEXT NOT NULL,"serviceTypeId" TEXT NOT NULL REFERENCES "PlatformServiceType"("id") ON DELETE CASCADE,"skills" TEXT[] NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY("staffId","serviceTypeId"),FOREIGN KEY ("businessId","staffId") REFERENCES "Staff"("businessId","id") ON DELETE CASCADE);
CREATE TABLE "CategoryResultSchema" ("id" TEXT PRIMARY KEY,"categoryId" TEXT NOT NULL REFERENCES "PlatformCategory"("id") ON DELETE CASCADE,"version" INTEGER NOT NULL,"schema" JSONB NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("categoryId","version"));
CREATE INDEX "Service_businessId_platformCategoryId_platformSubcategoryId_platformServiceTypeId_idx" ON "Service"("businessId","platformCategoryId","platformSubcategoryId","platformServiceTypeId");
CREATE INDEX "TenantCategoryConfiguration_businessId_enabled_categoryId_idx" ON "TenantCategoryConfiguration"("businessId","enabled","categoryId");
CREATE INDEX "PlatformResource_businessId_resourceTypeId_isActive_idx" ON "PlatformResource"("businessId","resourceTypeId","isActive");
CREATE INDEX "ProfessionalServiceTypeAssignment_businessId_serviceTypeId_isActive_idx" ON "ProfessionalServiceTypeAssignment"("businessId","serviceTypeId","isActive");
